<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad,onPullDownRefresh } from '@dcloudio/uni-app'
import WareState from '@/shared/components/WareState.vue'
import { distributionApi } from '@/features/distribution/api/distribution.api'
import type { DistributionFilterOption } from '@/features/distribution/models/distribution'
import { restockApi } from '../../api/restock.api'
import type { RestockPlan,RestockPlanItem } from '../../models/restock'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'

const date=ref(new Date().toISOString().slice(0,10)),status=ref(0),serialNo=ref(''),zone=ref(''),draftZone=ref(''),zoneVisible=ref(false),zones=ref<DistributionFilterOption[]>([]),plans=ref<RestockPlan[]>([]),loading=ref(false),error=ref(''),expanded=ref(0),detailLoading=ref(0),details=ref<Record<number,RestockPlanItem[]>>({})
const sessionPickerVisible=ref(false)
const tabs=[{label:'全部',value:0},{label:'待出库',value:1},{label:'配货中',value:2},{label:'已完成',value:3}]
const statusText=(value:number)=>value===1?'待出库':value===2?'配货中':value===3?'已完成':'未知状态'
const rankText=(rank:number)=>['','A级','B级','C级','D级','E级'][rank]||`${rank}级`
const resultCount=computed(()=>plans.value.length)
async function load(){loading.value=true;error.value='';try{plans.value=await restockApi.plans(date.value,{status:status.value,serialNo:serialNo.value.trim(),zone:zone.value})}catch(e){error.value=e instanceof Error?e.message:'历史补货单加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
async function loadZones(){try{zones.value=await distributionApi.filterOptions(date.value);if(zone.value&&!zones.value.some(item=>item.zone===zone.value))zone.value=''}catch{zones.value=[];zone.value=''}}
async function changeDate(value:string){date.value=value;await loadZones();load()}
function openZone(){draftZone.value=zone.value;zoneVisible.value=true}
function confirmZone(){zone.value=draftZone.value;zoneVisible.value=false;load()}
function changeStatus(value:number){status.value=value;expanded.value=0;load()}
async function toggleDetail(plan:RestockPlan){if(expanded.value===plan.id){expanded.value=0;return}expanded.value=plan.id;if(details.value[plan.id])return;detailLoading.value=plan.id;try{details.value={...details.value,[plan.id]:await restockApi.planItems(plan.id)}}catch(e){uni.showToast({title:e instanceof Error?e.message:'补货详情加载失败',icon:'none'})}finally{detailLoading.value=0}}
onLoad(async query=>{if(query?.date)date.value=String(query.date);await loadZones();load()});onPullDownRefresh(load)
</script>

<template><view class="page">
  <view class="filters"><view class="picker-control" @click="sessionPickerVisible=true">{{date}}<text class="down"/></view><view class="picker-control" @click="openZone">{{zone?(zones.find(item=>item.zone===zone)?.areaName||`${Number(zone)}区`):'全部分区'}}<text class="down"/></view><view class="search"><text>#</text><input v-model="serialNo" type="number" placeholder="流水号" confirm-type="search" @confirm="load"/><button @click="load">查询</button></view></view>
  <view class="tabs"><view v-for="tab in tabs" :key="tab.value" :class="{active:status===tab.value}" @click="changeStatus(tab.value)">{{tab.label}}</view><text>共 {{resultCount}} 单</text></view>
  <WareState v-if="loading" type="loading" title="正在加载历史补货单"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重新加载" @action="load"/><WareState v-else-if="!plans.length" type="empty" title="暂无历史补货单" description="当前场次和筛选条件下没有补货计划"/>
  <view v-else class="list"><view v-for="plan in plans" :key="plan.id" class="card" @click="toggleDetail(plan)"><view class="card-head"><strong>#{{plan.serialNo}}</strong><text :class="['status',`s${plan.status}`]">{{statusText(plan.status)}}</text></view><view class="metrics"><view><text>计划补货</text><strong>{{plan.totalNeedNum}}扎</strong></view><view><text>已匹配</text><strong>{{plan.allocatedNum}}扎</strong></view><view><text>出库进度</text><strong>{{plan.prepareNum}}/{{plan.allocatedNum}}</strong></view></view><view class="meta"><text>{{plan.zones.length?plan.zones.map(zone=>`${Number(zone)}区`).join('、'):'未记录分区'}}</text><text>{{String(plan.createTime||'').slice(0,16).replace('T',' ')}}</text><text class="arrow" :class="{open:expanded===plan.id}"/></view>
    <view v-if="expanded===plan.id" class="detail" @click.stop><text v-if="detailLoading===plan.id" class="detail-state">正在加载商品明细…</text><text v-else-if="!details[plan.id]?.length" class="detail-state">暂无商品明细</text><view v-else><view class="detail-head"><text>商品</text><text>需求</text><text>匹配</text><text>出库</text></view><view v-for="item in details[plan.id]" :key="`${item.productName}-${item.rank}-${item.zone}`" class="detail-row"><view><strong>{{item.productName}} {{rankText(item.rank)}}</strong><small>{{item.skuConfig}} · {{Number(item.zone)}}区</small></view><text>{{item.needNum}}</text><text>{{item.allocatedNum}}</text><text>{{item.prepareNum}}</text></view></view></view>
  </view></view>
  <view v-if="zoneVisible" class="mask" @click="zoneVisible=false"><view class="drawer" @click.stop><view class="drawer-head"><strong>选择分区</strong><text @click="confirmZone">确定</text></view><scroll-view scroll-y class="zone-scroll"><view class="zone-grid"><view :class="{active:!draftZone}" @click="draftZone=''">全部分区</view><view v-for="item in zones" :key="item.zone" :class="{active:draftZone===item.zone}" @click="draftZone=item.zone">{{item.areaName||`${Number(item.zone)}区`}}</view></view></scroll-view></view></view>
  <SessionDatePicker v-model="date" v-model:visible="sessionPickerVisible" @confirm="changeDate"/>
</view></template>

<style scoped lang="scss">
.page{min-height:100vh;padding:24rpx}.filters{display:grid;grid-template-columns:230rpx 1fr;gap:12rpx}.date,.search{display:flex;height:68rpx;align-items:center;border-radius:15rpx;background:#fff}.date{justify-content:space-between;padding:0 18rpx;color:var(--wms-primary-700);font-size:21rpx}.down{width:9rpx;height:9rpx;border-right:2rpx solid currentColor;border-bottom:2rpx solid currentColor;transform:rotate(45deg) translateY(-3rpx)}.search{padding-left:16rpx;color:var(--wms-text-secondary)}.search input{min-width:0;flex:1;margin-left:4rpx;font-size:21rpx}.search button{width:88rpx;height:68rpx;margin:0;border:0;border-radius:0 15rpx 15rpx 0;background:var(--wms-primary-700);color:#fff;font-size:20rpx;line-height:68rpx}.search button:after{border:0}.tabs{display:flex;height:82rpx;align-items:center;gap:28rpx;border-bottom:1rpx solid var(--wms-border)}.tabs view{position:relative;color:var(--wms-text-secondary);font-size:21rpx}.tabs .active{color:var(--wms-primary-700);font-weight:700}.tabs .active:after{position:absolute;right:0;bottom:-29rpx;left:0;height:4rpx;border-radius:4rpx;background:var(--wms-primary-700);content:''}.tabs>text{margin-left:auto;color:var(--wms-text-secondary);font-size:18rpx}.list{display:flex;flex-direction:column;gap:14rpx;margin-top:18rpx}.card{padding:20rpx;border-radius:20rpx;background:#fff;box-shadow:var(--wms-shadow-card)}.card-head,.meta{display:flex;align-items:center;justify-content:space-between}.card-head strong{font-size:29rpx}.status{padding:6rpx 12rpx;border-radius:9rpx;font-size:18rpx}.s1{background:#fff2dd;color:#a86100}.s2{background:var(--wms-surface-soft);color:var(--wms-primary-700)}.s3{background:#e9f6ee;color:#268451}.metrics{display:grid;grid-template-columns:repeat(3,1fr);margin-top:17rpx;padding:16rpx 0;border-top:1rpx solid var(--wms-border);border-bottom:1rpx solid var(--wms-border)}.metrics view{padding-left:16rpx;border-left:1rpx solid var(--wms-border)}.metrics view:first-child{padding-left:0;border:0}.metrics text,.metrics strong{display:block}.metrics text{color:var(--wms-text-secondary);font-size:17rpx}.metrics strong{margin-top:5rpx;font-size:22rpx}.meta{position:relative;margin-top:14rpx;padding-right:30rpx;color:var(--wms-text-secondary);font-size:17rpx}.arrow{position:absolute;right:3rpx;width:10rpx;height:10rpx;border-right:2rpx solid currentColor;border-bottom:2rpx solid currentColor;transform:rotate(45deg)}.arrow.open{transform:rotate(225deg)}.detail{margin-top:17rpx;padding-top:15rpx;border-top:1rpx solid var(--wms-border)}.detail-state{display:block;padding:18rpx;color:var(--wms-text-secondary);font-size:19rpx;text-align:center}.detail-head,.detail-row{display:grid;grid-template-columns:minmax(0,1fr) 70rpx 70rpx 70rpx;align-items:center;gap:8rpx;text-align:center}.detail-head{padding:8rpx 0;color:var(--wms-text-secondary);font-size:17rpx}.detail-head text:first-child{text-align:left}.detail-row{padding:13rpx 0;border-top:1rpx solid var(--wms-border);font-size:19rpx}.detail-row>view{text-align:left}.detail-row strong,.detail-row small{display:block}.detail-row strong{font-size:19rpx}.detail-row small{margin-top:4rpx;color:var(--wms-text-secondary);font-size:16rpx}
.filters{grid-template-columns:1fr 1fr}.picker-control{display:flex;height:68rpx;align-items:center;justify-content:space-between;padding:0 18rpx;border-radius:15rpx;background:#fff;color:var(--wms-primary-700);font-size:21rpx}.search{grid-column:1/-1}
.mask{position:fixed;z-index:30;inset:0;display:flex;align-items:flex-end;background:rgba(15,28,26,.42)}.drawer{box-sizing:border-box;width:100%;max-height:86vh;padding:25rpx 24rpx calc(30rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.drawer-head{display:flex;align-items:center;justify-content:space-between}.drawer-head strong{font-size:29rpx}.drawer-head text{color:var(--wms-primary-700);font-size:23rpx}.zone-scroll{max-height:70vh;margin-top:22rpx}.zone-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14rpx}.zone-grid view{height:70rpx;border:2rpx solid transparent;border-radius:9rpx;background:#f0f2f2;font-size:22rpx;line-height:70rpx;text-align:center}.zone-grid .active{border-color:var(--wms-primary-700);background:var(--wms-surface-soft);color:var(--wms-primary-700)}
</style>
